"""1977~1979 원고(11/25~12/3)를 queue/*.json으로 만든다. 메타데이터는 m77/meta.json(iTunes·Spotify 확인본)."""
import json, os, sys

META = json.load(open(sys.argv[1]))
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
W = "https://en.wikipedia.org/wiki/"


def length(k, upto=None, override=None):
    if override:
        return override
    tr = META[k]["tracks"]
    if upto:
        tr = [t for t in tr if t[1] <= upto and t[0] == 1]
    mins = round(sum(t[3] for t in tr))
    rng = f"1–{upto}곡" if upto else f"{len(tr)}곡"
    return f"{rng} · {mins}분"


def A(k, artist, title, released, genre, blurb, upto=None, override=None, short=None):
    return {"id": k, "artist": artist, "title": title, "short": short or title, "released": released, "genre": genre, "blurb": blurb,
            "length": length(k, upto, override), "spotify": META[k]["spotify"], "apple": f"https://music.apple.com/kr/album/{META[k]['apple']}"}


