DAYS.append(dict(date="2026-11-28", part="1978-P1", year=1978, partNo=1, partTotal=3, total="약 114분",
  title="두 손으로 친 기타, 화가 난 안경잡이, 로봇이 된 밴드",
  intro="1978년은 디스코의 해였다. 〈토요일 밤의 열기〉 사운드트랙이 상반기 내내 미국 앨범 차트 1위를 지켰고, 록 밴드들도 춤추는 박자를 의식하기 시작했다. 한편 1977년에 폭발한 펑크는 금세 두 갈래로 나뉘었다. 하나는 펑크의 속도와 날카로움에 1960년대 팝의 짜임새를 더한 뉴 웨이브(New Wave)였고, 다른 하나는 기타 대신 신시사이저로 새 소리를 찾는 흐름이었다. 그 사이에서 기타 록도 사라지지 않았다. 오늘의 세 음반은 같은 해 초 거의 같은 시기에 나왔지만 각각 기타 연주의 극한, 뉴 웨이브의 말솜씨, 기계가 된 밴드를 들려준다.",
  albums=[A("van-halen", "Van Halen", "Van Halen", "1978년 2월", "하드 록", "에디 밴 헤일런의 태핑 기타로 1980년대 록 기타의 문법을 바꾼 데뷔작."),
          A("this-years-model", "Elvis Costello & The Attractions", "This Year's Model", "1978년 3월", "뉴 웨이브", "펑크의 속도에 1960년대 팝의 솜씨와 독설을 더한 코스텔로와 어트랙션스의 첫 음반."),
          A("man-machine", "Kraftwerk", "The Man-Machine", "1978년 5월", "신스팝", "밴드가 스스로 로봇이 되겠다고 선언한, 신스팝의 설계도 같은 음반.")],
  essays=[
   dict(id="van-halen", heading="두 손으로 친 기타", paras=[
    "1분 40초짜리 연주곡 〈Eruption〉은 많은 기타리스트의 인생을 바꾼 곡으로 꼽힌다. 에디 밴 헤일런은 오른손 손가락으로 지판을 직접 두드려 왼손이 짚은 음과 번갈아 울리게 하는 태핑(Tapping)으로, 사람 손으로는 불가능해 보이는 속도의 음들을 쏟아 낸다. 트레몰로 암으로 음정을 깊이 끌어내렸다 올리는 소리, 여러 부품을 직접 조립한 기타에서 나오는 따뜻하고 묵직한 일그러짐도 그만의 소리였다. 그 기타가 곡 전체를 끌고 가는 사이 보컬 데이비드 리 로스는 무대 위 쇼맨처럼 소리치고 웃는다. 킹크스의 〈You Really Got Me〉를 다시 부른 곡도 실려 있다.",
    "밴 헤일런은 캘리포니아 패서디나의 클럽과 파티에서 연주하던 밴드였다. 음반은 공연하듯 거의 한 번에 연주해 짧은 기간에 녹음했고, 덧입힌 소리가 많지 않아서 밴드가 한 방에서 내는 열기가 그대로 들린다. 펑크가 기교를 버리자고 외치던 바로 그때, 이 음반은 정반대로 기교를 신나는 파티의 언어로 만들었다.",
    "이후 1980년대 하드 록과 헤비메탈 기타리스트들이 너도나도 태핑을 익혔다. 에디는 1982년 마이클 잭슨의 〈Beat It〉에서 기타 독주를 맡기도 했다. 1969년 레드 제플린의 두 번째 음반과 이어 들으면 하드 록 기타가 10년 사이 어떻게 달라졌는지 들린다."]),
   dict(id="this-years-model", heading="화가 난 안경잡이의 팝", paras=[
    "〈No Action〉이 시작되면 스티브 나이브의 오르간이 날카롭게 울리고, 브루스 토머스의 베이스가 쉬지 않고 선율을 만들며 뛰어다닌다. 피트 토머스의 드럼까지 세 사람의 어트랙션스는 펑크만큼 빠르고 단단하지만, 곡의 짜임새는 1960년대 영국 팝처럼 정교하다. 〈Pump It Up〉에서 코스텔로는 짧은 문장을 쉼 없이 쏟아 내는데, 그는 밥 딜런의 〈Subterranean Homesick Blues〉에서 이 방식을 빌려 왔다고 말한 적이 있다. 사랑 노래처럼 들리는 곡들도 들어 보면 질투와 모욕, 미디어에 대한 조롱으로 가득하다.",
    "본명이 디클랜 맥머너스인 코스텔로는 컴퓨터 오퍼레이터로 일하며 곡을 쓰다가 1977년 데뷔했다. 1977년 12월 미국 〈새터데이 나이트 라이브〉에 출연했을 때 음반사가 원한 곡을 연주하다 멈추고, 라디오 방송국을 비판하는 〈Radio Radio〉로 바꿔 부르는 바람에 오랫동안 그 방송에 출연하지 못했다는 일화가 유명하다.",
    "펑크의 분노에 노래 만드는 솜씨를 더한 이 음반은 뉴 웨이브의 대표작이 됐다. 1965년 딜런의 《Bringing It All Back Home》과 이어 들으면, 말을 쏟아 내는 노래가 13년 뒤 어떤 리듬으로 바뀌었는지 비교할 수 있다."]),
   dict(id="man-machine", heading="스스로 로봇이 된 밴드", paras=[
    "첫 곡 〈The Robots〉에서는 보코더로 바꾼 목소리가 ‘우리는 로봇’이라고 반복한다. 신시사이저가 짠 반복 리듬은 기계처럼 정확하고, 선율은 단순하지만 귀에 오래 남는다. 〈The Model〉은 모델의 화려한 삶을 무심하게 묘사하는 3분짜리 신시사이저 팝인데, 발표 당시보다 1982년에 다시 나왔을 때 영국 싱글 차트 1위에 올랐다. 9분짜리 〈Neon Lights〉는 밤의 도시 불빛을 느리고 아름다운 반복으로 그린다.",
    "크라프트베르크는 무대 위의 스타라는 존재 자체를 지우고 싶어 했다. 멤버들은 똑같은 빨간 셔츠와 검은 넥타이를 맞춰 입었고, 표지는 1920년대 러시아 구성주의 화가 엘 리시츠키의 디자인을 본떴다. 나중에는 자신들과 똑같이 생긴 마네킹 로봇을 무대에 세우기도 했다. 연주자 개인의 감정과 기교보다 기계와 디자인의 정확함을 앞세운 태도였다.",
    "1980년대 휴먼 리그, 디페시 모드 같은 영국 신스팝 밴드들은 이 음반에서 출발했다. 1977년 《Trans-Europe Express》와 이어 들으면 같은 밴드가 1년 만에 실험에서 팝으로 얼마나 가까워졌는지 들린다."])],
  readings=[("Van Halen (album) · Wikipedia", W + "Van_Halen_(album)"), ("This Year's Model · Wikipedia", W + "This_Year%27s_Model"),
            ("The Man-Machine · Wikipedia", W + "The_Man-Machine"), ("New wave music · Wikipedia", W + "New_wave_music")],
  edges=[dict(**{"from": "led-zep2", "to": "van-halen", "type": "listen", "label": "하드 록 기타가 10년 사이 어떻게 달라졌는지"}),
         dict(**{"from": "bringing-home", "to": "this-years-model", "type": "listen", "label": "말을 쏟아 내는 노래가 13년 뒤 펑크의 리듬으로"}),
         dict(**{"from": "trans-europe", "to": "man-machine", "type": "document", "label": "같은 밴드의 다음 정규 음반", "source": W + "The_Man-Machine"})]))

DAYS.append(dict(date="2026-11-29", part="1978-P2", year=1978, partNo=2, partTotal=3, total="약 118분",
  title="디스코를 삼킨 롤링 스톤스, 디스코의 설계자들, 퇴화를 노래한 밴드",
  intro="1978년 여름 뉴욕의 밤은 디스코 클럽 스튜디오 54가 상징했다. 유명인들이 줄을 서서 들어가려 했고, 문 앞에서 거절당하는 일도 뉴스가 됐다. 디스코는 흑인과 라틴계, 동성애자 공동체의 클럽에서 자라 세계적인 유행이 됐는데, 그 인기가 커질수록 록 팬들 사이에서는 반감도 함께 커졌다. 오늘의 세 음반은 디스코를 대하는 세 가지 태도다. 롤링 스톤스는 디스코 박자를 받아들여 새 전성기를 열었고, 시크는 디스코를 가장 정교한 연주 음악으로 다듬었으며, 디보는 유행을 쫓는 인간이 오히려 퇴화하고 있다고 비꼬았다.",
  albums=[A("some-girls", "The Rolling Stones", "Some Girls", "1978년 6월", "록 · 디스코 록", "펑크와 디스코의 뉴욕에 맞서 롤링 스톤스가 다시 날을 세운 1970년대 후반의 대표작."),
          A("cest-chic", "Chic", "C'est Chic", "1978년 8월", "디스코", "〈Le Freak〉로 디스코의 기타와 베이스를 새로 쓴 나일 로저스와 버나드 에드워즈의 음반."),
          A("devo", "Devo", "Q: Are We Not Men? A: We Are Devo!", "1978년 8월", "뉴 웨이브", "인류가 퇴화하고 있다는 농담을 각진 리듬으로 들려준, 브라이언 이노가 제작한 데뷔작.", short="Q: Are We Not Men?")],
  essays=[
   dict(id="some-girls", heading="디스코를 삼킨 록 밴드", paras=[
    "첫 곡 〈Miss You〉에서 찰리 와츠는 디스코처럼 매 박마다 킥 드럼을 밟고, 빌 와이먼의 베이스는 춤추듯 오르내리며, 믹 재거는 가성을 섞어 노래한다. 그런데 하모니카와 끈적한 기타가 들어오면 이 곡은 여전히 롤링 스톤스의 블루스다. 〈Beast of Burden〉에서는 키스 리처즈와 새로 합류한 론 우드의 기타가 서로의 빈자리를 메우며 느슨하게 얽히고, 〈Shattered〉에서는 재거가 망가진 뉴욕의 거리를 쉴 새 없이 지껄이듯 노래한다.",
    "1970년대 중반 롤링 스톤스는 펑크 세대에게 낡은 공룡으로 조롱받았다. 리처즈는 1977년 캐나다에서 마약 혐의로 체포돼 재판을 앞두고 있었다. 밴드는 파리의 스튜디오에서 이 음반을 녹음하면서 펑크의 속도와 디스코의 박자, 범죄와 쓰레기로 뒤덮인 1970년대 후반 뉴욕의 공기를 끌어들였다. 그 결과는 미국 앨범 차트 1위와 밴드의 상업적 부활이었다.",
    "1972년 《Exile on Main St.》와 이어 들으면 같은 밴드가 6년 만에 남부의 흙냄새에서 뉴욕의 클럽으로 옷을 갈아입은 것이 들린다."]),
   dict(id="cest-chic", heading="디스코를 설계한 두 사람", paras=[
    "〈Le Freak〉에서 가장 먼저 귀에 들어오는 것은 나일 로저스의 기타다. 화음을 길게 울리지 않고 짧게 끊어 긁으며 리듬 악기처럼 쓰는데, 이 방식은 이후 수많은 댄스 음악의 기본이 됐다. 버나드 에드워즈의 베이스는 단순히 박을 받치지 않고 노래처럼 선율을 만들며, 토니 톰슨의 드럼과 현악기, 여러 명의 코러스가 그 위에 깔끔하게 놓인다. 〈I Want Your Love〉에서는 종소리 같은 소리와 현악기가 어우러져 우아하고 쓸쓸한 분위기를 만든다.",
    "〈Le Freak〉에는 유명한 탄생 일화가 있다. 1977년 마지막 날 로저스와 에드워즈는 초대를 받고 스튜디오 54에 갔지만 문 앞에서 입장을 거절당했다. 화가 나서 집으로 돌아와 문지기에게 퍼붓던 욕설로 즉흥 연주를 했고, 그 욕설이 ‘Freak out!’이라는 후렴으로 바뀌었다는 것이다. 이 곡은 당시 애틀랜틱 음반사 역사상 가장 많이 팔린 싱글이 된 것으로 알려져 있다.",
    "로저스는 이후 데이비드 보위의 《Let's Dance》, 마돈나의 〈Like a Virgin〉, 2013년 다프트 펑크의 〈Get Lucky〉까지 40년 넘게 댄스 팝의 소리를 만들었다. 1975년 어스 윈드 앤드 파이어와 이어 들으면 대형 소울 밴드의 정교함이 디스코로 어떻게 옮겨 갔는지 들린다."]),
   dict(id="devo", heading="인간은 퇴화하고 있다", paras=[
    "디보의 리듬은 몸이 부드럽게 흔들리는 그루브와 정반대다. 기타는 짧고 각지게 끊기고, 드럼은 기계처럼 딱딱하며, 신시사이저의 삑삑거리는 소리가 그 사이를 찌른다. 롤링 스톤스의 〈(I Can't Get No) Satisfaction〉을 다시 부른 곡에서는 원곡의 유명한 기타 리프를 거의 지워 버리고 뻣뻣한 박자만 남겨서, 원래 노래가 담고 있던 욕망을 신경질적인 경련처럼 바꿔 놓는다. 〈Jocko Homo〉에서는 ‘우리는 인간이 아닌가?’라는 물음에 ‘우리는 디보다!’라고 답하는 구호가 홀수 박자 위에서 되풀이된다.",
    "디보는 오하이오 애크런과 켄트 주립대의 미술학도들이 만든 밴드다. 1970년 켄트 주립대에서 주 방위군이 반전 시위 학생들에게 총을 쏴 네 명이 숨진 사건을 멤버 제럴드 캐세일이 직접 목격했고, 이 경험이 인류가 진화가 아니라 퇴화(De-evolution)하고 있다는 그들의 생각으로 이어졌다. 데뷔 음반은 브라이언 이노가 제작했고, 서독 쾰른에서 대부분 녹음됐다.",
    "똑같은 작업복과 계단 모양의 빨간 모자 같은 시각 연출 덕분에, 디보는 1980년대 초 뮤직비디오 시대에 가장 먼저 어울리는 밴드가 됐다. 1974년 이노의 《Here Come the Warm Jets》와 이어 들으면 제작자 이노가 남의 음반에서 어떤 소리를 끌어냈는지 비교할 수 있다."])],
  readings=[("Some Girls · Wikipedia", W + "Some_Girls"), ("C'est Chic · Wikipedia", W + "C%27est_Chic"),
            ("Devo · Wikipedia", W + "Devo"), ("Studio 54 · Wikipedia", W + "Studio_54")],
  edges=[dict(**{"from": "exile", "to": "some-girls", "type": "listen", "label": "같은 밴드가 남부의 흙냄새에서 뉴욕의 클럽으로"}),
         dict(**{"from": "way-of-world", "to": "cest-chic", "type": "listen", "label": "대형 소울 밴드의 정교함이 디스코로"}),
         dict(**{"from": "eno-warm-jets", "to": "devo", "type": "document", "label": "브라이언 이노가 제작", "source": W + "Devo"})]))

