         dict(**{"from": "bollocks", "to": "unknown-pleasures", "type": "listen", "label": "섹스 피스톨스 공연을 본 맨체스터 청년들의 포스트펑크"}),
         dict(**{"from": "van-halen", "to": "highway-to-hell", "type": "listen", "label": "기교와 단순함, 하드 록의 두 방향"}),
